BLUEPRINT["Memo_IFRS9"] = {
  'col_widths': {'A': 18.0, 'B': 18.0, 'C': 18.0, 'D': 18.0, 'E': 18.0, 'F': 18.0, 'G': 18.0, 'H': 18.0},
  'row_heights': {1: 26.0, 2: 18.0, 35: 110.0},
  'merged': ['A43:H45', 'A19:H21', 'A55:H58', 'A1:H1', 'A9:H11', 'A30:H32', 'A48:H52', 'A54:H54', 'A18:H18', 'A35:H40', 'A2:H2', 'A42:H42', 'A24:H27', 'A47:H47', 'A23:H23', 'A8:H8', 'A22:H22', 'A4:H4', 'A29:H29', 'A14:H16', 'A13:H13', 'A34:H34'],
  'freeze': None,
  'cells': [
    ("A1","Hedge Memo (IFRS 9)",None),
    ("A2","Populate narrative fields and supporting tables below",None),
    ("A4","Hedging relationship summary",None),
    ("A5","Entity",None),
    ("B5","=Inputs!B5",None),
    ("D5","Hedge type",None),
    ("E5","=Inputs!B7",None),
    ("A6","Designation date",None),
    ("B6","=Inputs!B8","yyyy-mm-dd"),
    ("D6","De-designation date",None),
    ("E6","=Inputs!B9","yyyy-mm-dd"),
    ("A8","1. Background",None),
    ("A9","The entity has HKD floating-rate debt exposing it to variability in future cash flows driven by changes in 3M HIBOR. The entity uses an interest rate swap (IRS) to convert the benchmark-rate component of the debt\u2019s cash flows to a fixed profile, consistent with its treasury risk management objective.",None),
    ("A13","2. Hedged item (IFRS 9.6.4.1)",None),
    ("A14","=\"Hedged item: forecast quarterly interest cash flows on HKD floating-rate debt (Reval 3567) on a notional of HKD \"&TEXT(Inputs!$B$16,\"#,##0\")&\", referencing \"&Inputs!B17&\". Contractual spread of \"&TEXT(Inputs!$B$18,\"0\")&\" bps is typically excluded from designation unless specified.\"",None),
    ("A18","3. Hedging instrument (IFRS 9.6.4.1)",None),
    ("A19","=\"Hedging instrument: HKD interest rate swap (IRS) Reval 3566 under counterparty reference CPLIRS001, notional HKD \"&TEXT(Inputs!$B$29,\"#,##0\")&\", settling quarterly. The IRS pays fixed at \"&TEXT(Inputs!$B$31,\"0.000000%\")&\" and receives \"&Inputs!B32&\".\"",None),
    ("A22","Hypothetical derivative (for effectiveness measurement): Dummy IRS Reval 3568 constructed to proxy PV changes of the hedged item attributable to the hedged risk. Used in Retro_Test and Regression.",None),
    ("A23","4. Risk management objective and strategy",None),
    ("A24","Objective: Reduce variability in cash flows attributable to movements in the benchmark interest rate (3M HIBOR) on HKD debt by entering into an IRS.\nStrategy: Maintain a hedge ratio of 1:1 between the designated notional of the debt and the IRS notional.",None),
    ("A29","5. Hedged risk",None),
    ("A30","Designated hedged risk: variability in the debt\u2019s cash flows attributable to changes in 3M HIBOR (benchmark component). The contractual credit spread is typically excluded from designation.",None),
    ("A34","6. Hedge effectiveness assessment (qualitative + quantitative)",None),
    ("A35","Qualitative: Critical terms (currency, notional, index tenor, reset/payment frequencies) are assessed and monitored; sources of ineffectiveness are identified.\nQuantitative: Regression of periodic changes in fair value (\u0394FV) of the hedging instrument (Reval 3566) versus the hypothetical derivative (Reval 3568) is performed and refreshed on an on-going basis (see 'MTM_Input', 'Effectiveness_Regression' and 'Prospective_Ongoing'). Retrospective 80\u2013125% dollar-offset monitoring using the same two series is available (see 'Retro_Test').",None),
    ("A42","7. Credit risk and dominance assessment",None),
    ("A43","Consistent with treasury risk management policy, the IRS counterparty is expected to be rated A- (S&P) / A3 (Moody\u2019s) or above, or ALCO-approved. Credit risk is not expected to dominate value changes at inception; reassess upon significant changes.",None),
    ("A47","8. Sources of ineffectiveness",None),
    ("A48","\u2022 Timing differences of 3M HIBOR fixing and cash flow payment dates between IRS and debt\n\u2022 Changes in 3M HIBOR\n\u2022 Changes in designated notional amounts\n\u2022 Significant change in credit risk of either party",None),
    ("A54","9. Accounting treatment (cash flow hedge)",None),
    ("A55","Effective portion of the hedge instrument\u2019s fair value change is recorded in OCI (cash flow hedge reserve). Ineffectiveness is recognized in profit or loss. Recycling of OCI to profit or loss is aligned to hedged cash flows. See 'OCI_Ineffectiveness' and 'PnL_and_Journals' for roll-forward and journals. Sensitivity is in 'Sensitivity'.",None),
  ],
}

