def build_workbook(out_path: str) -> None:
    wb = Workbook()
    # Remove default sheet
    wb.remove(wb.active)
    # Create sheets in correct order
    for sname in SHEET_ORDER:
        ws = wb.create_sheet(title=sname)
        bp = BLUEPRINT[sname]
        # Column widths
        for col, w in bp['col_widths'].items():
            ws.column_dimensions[col].width = float(w)
        # Row heights
        for r, h in bp['row_heights'].items():
            ws.row_dimensions[int(r)].height = float(h)
        # Merged cells
        for rng in bp['merged']:
            ws.merge_cells(rng)
        # Freeze panes
        if bp['freeze']:
            ws.freeze_panes = bp['freeze']
        # Cell values + number formats
        for coord, v, fmt in bp['cells']:
            cell = ws[coord]
            if isinstance(v, tuple) and len(v)==2 and v[0]=='datetime':
                cell.value = datetime.datetime.fromisoformat(v[1])
            else:
                cell.value = v
            if fmt:
                cell.number_format = fmt

    # Named ranges
    for nm, ref in NAMED_RANGES.items():
        dn = DefinedName(name=nm, attr_text=ref)
        wb.defined_names.add(dn)

    # Ask Excel to recalc on open
    try:
        wb.calculation.fullCalcOnLoad = True
    except Exception:
        pass

    wb.save(out_path)

if __name__ == '__main__':
    build_workbook('IFRS9_Hedge_Memo_Pack_CITIC_CPLIRS001_v24_rebuilt_from_scratch.xlsx')
    print('Saved IFRS9_Hedge_Memo_Pack_CITIC_CPLIRS001_v24_rebuilt_from_scratch.xlsx')